import random

def generate_permutations(s):
    l = list(s)
    return all_perms(l)

def all_perms(lst):
    if len(lst) <= 1:
        return [lst]
    else:
        res = []
        for i in range(len(lst)):
            c = lst[i]
            rem = [lst[j] for j in range(len(lst)) if j != i]
            for p in all_perms(rem):
                res.append([c] + p)
        return res

