class Lexer:
    def __init__(self, filename):
        self.filename = filename
        self.re = re.compile(r'(assert|log)')

    def process(self):
        for line in open(self.filename):
            tokens = self.re.findall(line)
            for token in tokens:
                if token == 'assert':
                    log('Assert found')
                elif token == 'log':
                    log('Log found')

