from collections import deque

class Map:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.grid = [[0 for _ in range(cols)] for _ in range(rows)]

    def apply_move(self, row, col, move):
        new_row = row
        new_col = col

        if move == 'N':
            new_row -= 1
        elif move == 'S':
            new_row += 1
        elif move == 'W':
            new_col -= 1
        elif move == 'E':
            new_col += 1

        if new_row not in range(self.rows) or new_col not in range(self.cols):
            return

        self.grid[new_row][new_col] = 1

def show_path(grid, visitor):
    url = 'https://mywebsite.com/map.png'
    return f'<img src="{url}" width="{grid.cols * 50}" height="{grid.rows * 50}"><br>{visitor} visited:'
                    + '<br>'.join(visitor.visited_moves)

