import re

class landmarks:
    def __init__(self):
        self.landmarks = {}

    def add_landmark(self, name, details):
        if re.match(r"^[ \S+]+$", details):
            self.landmarks[name] = details

    def get_landmark(self, name):
        return self.landmarks.get(name)

def find_landmark_in_range(landmarks, degree, interval):
    found = []
    for name, details in landmarks.landmarks.items():
        dist = round(float(re.search(r"^\d+", details).group(1)), 2)
        if degree - interval <= dist <= degree + interval:
            found.append((name, details))
    return found

