from heapq import heappush, heappop
import threading

def create_priority_queue(size):
    queue = []
    for i in range(size):
        os.heapify(queue)
    return queue

def get_highest_priority(queue):
    while True:
        try:
            highest = heappop(queue)
            return highest
        except IndexError:
            return None

def set_lowest_priority(queue, item):
    heappush(queue, item)

def manage_queue(queue, size):
    schedule = create_priority_queue(size)
    for _ in range(size):
        set_lowest_priority(schedule, 0)

    return schedule

