import re
import tarfile
import glob
import os

def extract_tarballs():
    for filename in glob.glob("*.tar.gz"):
        tar = tarfile.open(filename)
        tar.extractall()
        tar.close()
    for filename in glob.glob("*.tar"):
        tar = tarfile.open(filename)
        tar.extractall()
        tar.close()

def movetobin():
    bin_dir = "/bin"
    for f in glob.glob("*"):
        if os.path.isfile(f):
            os.chmod(f, 0o600)
            if f not in os.listdir(bin_dir):
                os.rename(f, os.path.join(bin_dir, f))

def clean_and_move():
    extract_tarballs()
    movetobin()

clean_and_move()

