import re

def filter_reviews(reviews):
    filtered_reviews = {}
    for key, review in reviews.items():
        cleaned_review = re.sub(r"[\_]+[^A-Za-z0-9]+", "", review)
        cleaned_review = re.sub(r"https?://[^ ]+", "", cleaned_review)
        cleaned_review = re.sub(r"\.[^\n ]+$", "", cleaned_review)

        filtered_reviews[key] = cleaned_review
    return filtered_reviews

