def determine_distance(four_corner_word, alliances, alignment):
    distance = 0
    if len(four_corner_word) != 4:
        distance += 1
    if len(alliances) < 4:
        distance += 1
    if alignment in alliances:
        distance += 0
    else:
        distance += 1

    return distance

